HTTP Status: %{http_code}
" \ "$API_URL/api/v1/voice/health" \ -H "Content-Type: application/json" . Step 3: Check Backend Logs . #!/bin/bash # scripts/check-auth-logs.sh echo "📋 Checking Auth-Related Logs" echo "=============================" # Check for auth module load echo "" echo "1. Auth module load messages:" az containerapp logs show --name staging-env-api --resource-group engram-rg \ --tail 200 --type console 2&gt;&amp;1 | grep -iE "🔐|Auth module loaded|AUTH_REQUIRED" | tail -10 # Check for auth bypass messages echo "" echo "2. Auth bypass messages:" az containerapp logs show --name staging-env-api --resource-group engram-rg \ --tail 200 --type console 2&gt;&amp;1 | grep -iE "✅|Auth bypass|poc-user" | tail -10 # Check for 401 errors echo "" echo "3. 401 Unauthorized errors:" az containerapp logs show --name staging-env-api --resource-group engram-rg \ --tail 200 --type console 2&gt;&amp;1 | grep -iE "401|unauthorized|Missing.*token" | tail -10 # Check recent requests echo "" echo "4. Recent API requests:" az containerapp logs show --name staging-env-api --resource-group engram-rg \ --tail 50 --type console 2&gt;&amp;1 | grep -iE "POST|GET.*/api/v1" | tail -10 . Step 4: Verify Code Deployment . #!/bin/bash # scripts/verify-deployment.sh echo "🚀 Verifying Deployment" echo "======================" # Check latest commit echo "" echo "1. Latest commit:" git log -1 --oneline # Check GitHub Actions status echo "" echo "2. GitHub Actions deployment status:" gh run list --limit 1 --json status,conclusion,createdAt,headBranch \ --jq '.[] | "Status: \(.status), Conclusion: \(.conclusion // "N/A"), Created: \(.createdAt)"' # Check container revision echo "" echo "3. Active container revision:" az containerapp revision list --name staging-env-api --resource-group engram-rg \ --query "[0].{name:name, createdTime:properties.createdTime, active:properties.active}" \ --output json # Check if new code is running echo "" echo "4. Checking for new code indicators in logs:" az containerapp logs show --name staging-env-api --resource-group engram-rg \ --tail 100 --type console 2&gt;&amp;1 | grep -iE "🔐|Auth module loaded|conditional" | tail -5 . Step 5: Force Container Restart . #!/bin/bash # scripts/restart-backend.sh echo "🔄 Restarting Backend Container" echo "===============================" # Get current revision REVISION=$(az containerapp revision list --name staging-env-api \ --resource-group engram-rg \ --query "[0].name" -o tsv) echo "Current revision: $REVISION" # Restart echo "Restarting..." az containerapp revision restart \ --name staging-env-api \ --resource-group engram-rg \ --revision "$REVISION" echo "Waiting 30 seconds for container to restart..." sleep 30 echo "✅ Container restarted" .
